import csv
import io


def parse_csv(raw_csv: str):
    source = iter(io.StringIO(raw_csv, newline=""))
    at_record_start = True
    header_found = False
    record_lines = []

    def lines():
        nonlocal at_record_start
        for line in source:
            if at_record_start and line.lstrip().startswith("#"):
                if header_found:
                    continue
                candidate = line.lstrip()[1:].lstrip()
                try:
                    fields = next(csv.reader([candidate], skipinitialspace=True))
                except (csv.Error, StopIteration):
                    continue
                if len(fields) != 6:
                    continue
                line = candidate
            at_record_start = False
            record_lines.append(line)
            yield line

    def quoted_fields(text):
        flags = []
        i = 0
        n = len(text)
        while i < n:
            while i < n and text[i] == " ":
                i += 1
            quoted = i < n and text[i] == '"'
            flags.append(quoted)
            if quoted:
                i += 1
                while i < n:
                    if text[i] == '"':
                        if i + 1 < n and text[i + 1] == '"':
                            i += 2
                        else:
                            i += 1
                            break
                    else:
                        i += 1
            while i < n and text[i] not in ",\r\n":
                i += 1
            if i >= n or text[i] in "\r\n":
                break
            i += 1
            if i >= n or text[i] in "\r\n":
                flags.append(False)
                break
        return flags

    reader = csv.reader(lines(), skipinitialspace=True)
    columns = None
    rows = []

    while True:
        at_record_start = True
        record_lines.clear()
        try:
            record = next(reader)
        except StopIteration:
            break

        flags = quoted_fields("".join(record_lines))
        record = [
            value if i < len(flags) and flags[i] else value.strip()
            for i, value in enumerate(record)
        ]

        if columns is None:
            if not record:
                continue
            columns = record
            header_found = True
        else:
            rows.append(record)

    if columns is None:
        return {"columns": [], "rows": []}

    width = max([len(columns)] + [len(row) for row in rows])
    used = set(columns)
    while len(columns) < width:
        index = len(columns) + 1
        name = "column_{}".format(index)
        while name in used:
            name += "_"
        columns.append(name)
        used.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
